question.answer:
package main

type Weight int

type Ranked interface {
	~int | ~string
}

func top[T Ranked](entries []T) T {
	var best T
	for i, entry := range entries {
		if i == 0 || entry > best {
			best = entry
		}
	}
	return best
}

