question.answer:
package main

import "fmt"

type Catch[E any] struct {
	items []E
}

type Named interface {
	Label() string
}

func NewCatch[E any](entries ...E) Catch[E] {
	return Catch[E]{items: entries}
}

func (c Catch[E]) Items() []E {
	return c.items
}

func (c Catch[E]) Label() string {
	return fmt.Sprintf("%d entries", len(c.items))
}

func (c Catch[E]) Map[R any](convert func(E) R) Catch[R] {
	out := make([]R, 0, len(c.items))
	for _, item := range c.items {
		out = append(out, convert(item))
	}
	return Catch[R]{items: out}
}

func describe(n Named) string {
	return n.Label()
}

