question.answer:
package main

import "fmt"

type Crates int

type Vessel interface {
	Callsign() string
}

type Ferry struct {
	Name string
}

type Tug struct {
	Number int
}

type Tonnage interface {
	~int | ~float64
}

func (f Ferry) Callsign() string {
	return f.Name
}

func (t Tug) Callsign() string {
	return fmt.Sprintf("TUG-%d", t.Number)
}

func roll(vessels []Vessel) []string {
	calls := make([]string, 0, len(vessels))
	for _, vessel := range vessels {
		calls = append(calls, vessel.Callsign())
	}
	return calls
}

func total[T Tonnage](loads []T) T {
	var sum T
	for _, load := range loads {
		sum += load
	}
	return sum
}
